window.ATLAS_CATALOG_READY=(async()=>{try{const encoded="";const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));const payload=await new Response(stream).json();for(const product of payload.data.product){const svg=payload.vectors[product.name];if(svg){product.originalThumbnail=product.thumbnail;product.originalDetail=product.detail;product.detail=product.thumbnail='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}}window.ATLAS_CATALOG=payload.data;return payload.data}catch(error){const status=document.getElementById('result-count');if(status)status.textContent='Katalóg sa nepodarilo načítať. Obnovte stránku alebo použite aktuálny prehliadač.';throw error}})();